var l = ["<script", ' type="application/ld+json">', "<\/script>"], c = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], g = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>API 5L Pipe Guide</span></div>'], h = ["<main", ' style="', '"><div style="', '"><span style="', '">Specification Guide</span><span style="', '">June 2026 \xB7 9 min read</span><h1 style="', '">API 5L Pipe \u2014 The Global Standard for Oil and Gas Transport</h1><p style="', '">Every oil pipeline, gas transmission line, and subsea flowline on Earth is built with <strong>API 5L pipe</strong>. Developed by the American Petroleum Institute, this specification defines line pipe for the transport of petroleum products and natural gas from wellhead to refinery and beyond. As a specialist <strong>metal importer exporter in India</strong> supplying pipeline projects for ONGC, GAIL, IOCL, and EPC contractors, Creative Metal Industries sources API 5L pipes in all grades and manufacturing types.</p></div><h2 style="', '">Why API 5L is Essential for Pipeline Transportation</h2><p style="', '">Unlike process piping (governed by ASTM A106/A312), pipeline transportation has unique requirements: thousands of kilometres of pipe buried underground or laid on the seabed, operating for 30-50 years with minimal maintenance, often in remote locations. API 5L addresses these specific needs with grades designed for high-strength-to-weight ratio, weldability in field conditions, and resistance to hydrogen-induced cracking in sour environments.</p><p style="', '">The specification covers pipe manufactured by seamless, ERW (Electric Resistance Welded), HSAW (Helical Submerged Arc Welded), and LSAW (Longitudinal Submerged Arc Welded) processes \u2014 each suited to different diameter ranges and applications.</p><h2 style="', '">Product Specification Levels \u2014 PSL1 vs PSL2</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Requirement</th><th style="', '">PSL1</th><th style="', '">PSL2</th></tr></thead><tbody>', '</tbody></table></div><p style="', '">For Indian oil & gas projects (ONGC, GAIL, IOCL): PSL2 is almost always specified. PSL1 is used only for low-pressure water or non-critical utility lines.</p><h2 style="', '">Grades Explained \u2014 A25 Through X80</h2><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Grade</th><th style="', '">Min Yield (MPa)</th><th style="', '">Min Tensile (MPa)</th><th style="', '">Typical Use</th></tr></thead><tbody>', '</tbody></table></div><p style="', '">In India, X52 and X65 are the most commonly specified grades \u2014 X52 for standard onshore oil pipelines, X65 for high-pressure gas transmission (GAIL network). X70/X80 are used for transcontinental gas pipelines where wall thickness reduction justifies the higher grade cost.</p><h2 style="', '">Key Applications \u2014 Onshore and Offshore Pipelines</h2><div style="', '">', '</div><h2 style="', '">Why Source API 5L from Creative Metal Industries?</h2><ul style="', '"><li><strong>All manufacturing types:</strong> Seamless, ERW, HSAW (Helical SAW), LSAW (Longitudinal SAW) \u2014 sourced from Jindal SAW, Welspun, APL Apollo, Maharashtra Seamless, and imported mills</li><li><strong>Grade range:</strong> Grade B through X70 in PSL1 and PSL2. Sour service (NACE/HIC) grades available with supplementary requirements</li><li><strong>Coating coordination:</strong> 3LPE, 3LPP, FBE, and concrete weight coating \u2014 coordinated with approved coating yards for turnkey supply</li><li><strong>Project volumes:</strong> 50 MT to 5000+ MT \u2014 supplying ONGC, GAIL, GSPL, IOCL, and EPC contractors (L&T, Punj Lloyd, Essar) on pipeline projects</li><li><strong>Documentation:</strong> MTC 3.1/3.2, hydrostatic test certificates, NDE reports (UT/RT), NACE/HIC test reports \u2014 complete data book per project specification</li><li><strong>Global sourcing:</strong> As an experienced <strong>metal importer exporter in India</strong>, we source from mills worldwide when Indian capacity is constrained \u2014 ensuring project timelines are met</li></ul><h2 style="', '">Frequently Asked Questions \u2014 API 5L</h2><div style="', '">', '</div><div style="', '"><h2 style="', '">Need API 5L Line Pipes?</h2><p style="', '">Grade B to X70. PSL1 & PSL2. Seamless, ERW, HSAW, LSAW. Project quantities. NACE/HIC available.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/#contact" style="', '">Send Enquiry \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], f = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 API 5L Line Pipe Supplier India | Metal Importer Exporter</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], u = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], y = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], b = ["<div", ' style="', '"><span style="', '">', '</span><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], w = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], P = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
const A = JSON.stringify({ "@context": "https://schema.org", "@type": "Article", headline: "API 5L Pipe \u2014 The Global Standard for Oil and Gas Transport", author: { "@type": "Organization", name: "Creative Metal Industries" }, publisher: { "@type": "Organization", name: "Creative Metal Industries", logo: { "@type": "ImageObject", url: "https://www.creativemetalind.com/logo_cmi.png" } }, datePublished: "2026-06-17", image: "https://www.creativemetalind.com/img/line_pipes.webp", url: "https://www.creativemetalind.com/blog/api-5l-pipe-guide" }), L = JSON.stringify({ "@context": "https://schema.org", "@type": "FAQPage", mainEntity: [{ "@type": "Question", name: "What is API 5L pipe used for?", acceptedAnswer: { "@type": "Answer", text: "API 5L pipes are used for transporting oil, natural gas, and water in pipeline systems. This includes: onshore cross-country oil/gas pipelines, offshore subsea pipelines, gas gathering and distribution networks, water transmission mains, refinery and plant interconnecting pipelines, and city gas distribution systems. API 5L is THE global standard for line pipe \u2014 accepted by every major oil company worldwide." } }, { "@type": "Question", name: "What is the difference between PSL1 and PSL2?", acceptedAnswer: { "@type": "Answer", text: "PSL1 (Product Specification Level 1) is the standard quality level with basic testing requirements. PSL2 is the enhanced quality level requiring: mandatory Charpy impact testing at specified temperature, tighter chemical limits (max Carbon Equivalent), stricter dimensional tolerances, mandatory NDE of weld seam, and individual pipe traceability. For sour service (H\u2082S), offshore, or critical pipelines \u2014 PSL2 is always specified." } }, { "@type": "Question", name: "What do API 5L grades X42, X52, X65 mean?", acceptedAnswer: { "@type": "Answer", text: "The number after 'X' represents the minimum yield strength in ksi (thousand pounds per square inch). X42 = 42 ksi (290 MPa), X52 = 52 ksi (360 MPa), X65 = 65 ksi (450 MPa), X70 = 70 ksi (485 MPa), X80 = 80 ksi (555 MPa). Higher grade = thinner wall for same pressure rating = lighter, cheaper pipeline. But higher grades are harder to weld and less ductile." } }] });
